//! Copy-on-change SVG animation frame evaluation over an immutable scene.
#![forbid(unsafe_code)]
mod apply;
mod clips;
use apply::apply_value;
pub use clips::update_animation_clips;

use vexel_geometry::{affine_compose, affine_identity, affine_map_point};
use vexel_scene::{
    Affine, Diagnostic, Edge, ErrorKind, EvaluatedFrame, FrameBuilder, LimitKind, Paint, PaintKind,
    Result, SceneView, Shape, TransformFrame, WorkControl, WorkKind,
};
use vexel_svg_animation::{
    Attribute, EvaluationError, Kind, OverlayItem, Track, TransformType, Value, ValueKind,
    evaluate_view_controlled,
};

const CHAIN_MAX: usize = 128;
const WORK_MAX: usize = 50_000_000;
/// Default owned-frame byte ceiling, matching the original animation clip cap.
pub const DEFAULT_FRAME_BYTE_BUDGET: usize = 64 * 1024 * 1024;

fn diag(kind: ErrorKind, offset: usize) -> Diagnostic {
    Diagnostic { kind, offset }
}
fn invalid(offset: usize) -> Diagnostic {
    diag(ErrorKind::InvalidArgument, offset)
}
fn limit(kind: LimitKind) -> Diagnostic {
    diag(ErrorKind::Limit(kind), 0)
}
fn arithmetic() -> Diagnostic {
    limit(LimitKind::Arithmetic)
}
fn oom() -> Diagnostic {
    diag(ErrorKind::OutOfMemory, 0)
}
fn charge(control: &mut dyn WorkControl, amount: usize) -> Result<()> {
    let units = u64::try_from(amount).map_err(|_| arithmetic())?;
    control
        .charge(WorkKind::AnimationTransform, units)
        .map_err(|s| match s {
            vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
            vexel_scene::Stop::Limit => limit(LimitKind::Work),
            vexel_scene::Stop::Overflow => arithmetic(),
        })
}
fn count_work(work: &mut usize, amount: usize) -> Result<()> {
    *work = work.checked_add(amount).ok_or_else(arithmetic)?;
    if *work > WORK_MAX {
        return Err(limit(LimitKind::Work));
    }
    Ok(())
}
fn changes_clips(track: &Track, item: OverlayItem) -> bool {
    matches!(track.kind, Kind::Transform | Kind::Motion)
        || (matches!(track.kind, Kind::Animate | Kind::Set)
            && item.value.kind == ValueKind::Number
            && matches!(
                track.attribute,
                Attribute::X
                    | Attribute::Y
                    | Attribute::Cx
                    | Attribute::Cy
                    | Attribute::Width
                    | Attribute::Height
                    | Attribute::Rx
                    | Attribute::Ry
                    | Attribute::R
            ))
}
fn copy_table<T: Copy>(values: &[T], control: &mut dyn WorkControl) -> Result<Vec<T>> {
    let mut copy = Vec::new();
    copy.try_reserve_exact(values.len()).map_err(|_| oom())?;
    for value in values {
        control
            .charge(WorkKind::AnimationTransform, 1)
            .map_err(|s| match s {
                vexel_scene::Stop::Canceled => diag(ErrorKind::Canceled, 0),
                vexel_scene::Stop::Limit => limit(LimitKind::Work),
                vexel_scene::Stop::Overflow => arithmetic(),
            })?;
        copy.push(*value);
    }
    Ok(copy)
}

fn inverse(m: Affine, threshold: f64) -> Option<Affine> {
    let determinant = m.a * m.d - m.b * m.c;
    if !determinant.is_finite() || determinant.abs() < threshold {
        return None;
    }
    let k = 1.0 / determinant;
    let out = Affine {
        a: m.d * k,
        b: -m.b * k,
        c: -m.c * k,
        d: m.a * k,
        e: (m.c * m.f - m.d * m.e) * k,
        f: (m.b * m.e - m.a * m.f) * k,
    };
    vexel_geometry::affine_valid(out).then_some(out)
}
fn transform_value(track: &Track, value: Value) -> Option<Affine> {
    let x = value.number[0];
    let y = value.number[1];
    if !x.is_finite() || !y.is_finite() || x.abs() > 1e6 || y.abs() > 1e6 {
        return None;
    }
    let mut m = affine_identity();
    match track.transform_type {
        TransformType::Translate => {
            m.e = x;
            m.f = y;
        }
        TransformType::Scale => {
            m.a = x;
            m.d = if value.number[3] >= 2. { y } else { x };
        }
        TransformType::Rotate => {
            let angle = x * 0.017453292519943295769;
            let (s, c) = angle.sin_cos();
            if !s.is_finite() || !c.is_finite() {
                return None;
            }
            m = Affine {
                a: c,
                b: s,
                c: -s,
                d: c,
                e: 0.,
                f: 0.,
            };
            if value.number[3] >= 3. {
                let to = Affine {
                    e: value.number[1],
                    f: value.number[2],
                    ..affine_identity()
                };
                let from = Affine {
                    e: -value.number[1],
                    f: -value.number[2],
                    ..affine_identity()
                };
                m = affine_compose(affine_compose(to, m)?, from)?;
            }
        }
        TransformType::SkewX | TransformType::SkewY => {
            let t = (x * 0.017453292519943295769).tan();
            if !t.is_finite() || t.abs() > 1e6 {
                return None;
            }
            if track.transform_type == TransformType::SkewX {
                m.c = t
            } else {
                m.b = t
            }
        }
    }
    vexel_geometry::affine_valid(m).then_some(m)
}
fn product(
    transforms: &[TransformFrame],
    shape: &Shape,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<Affine> {
    let mut chain = [None; CHAIN_MAX];
    let mut count = 0;
    let mut node = shape.source.transform_node;
    while let Some(id) = node {
        if count == CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(shape.source.element.start));
        }
        charge(control, 1)?;
        *work = work.checked_add(1).ok_or_else(arithmetic)?;
        if *work > WORK_MAX {
            return Err(limit(LimitKind::Work));
        }
        chain[count] = Some(id);
        count += 1;
        node = transforms[id.index()].parent;
    }
    let mut out = affine_identity();
    while count > 0 {
        count -= 1;
        let n = transforms[chain[count].ok_or_else(|| invalid(0))?.index()];
        let local = affine_compose(n.attribute, n.suffix)
            .and_then(|m| affine_compose(n.motion, m))
            .ok_or_else(|| invalid(n.source_offset))?;
        out = affine_compose(out, local).ok_or_else(|| invalid(n.source_offset))?;
    }
    Ok(out)
}
fn shape_bounds(
    shape: &Shape,
    current_edges: &[Edge],
    inverse: Affine,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<[f64; 4]> {
    let edges = shape
        .edges
        .slice(current_edges)
        .ok_or_else(|| invalid(shape.source.element.start))?;
    if edges.is_empty() {
        return Err(invalid(shape.source.element.start));
    }
    charge(control, edges.len())?;
    *work = work.checked_add(edges.len()).ok_or_else(arithmetic)?;
    if *work > WORK_MAX {
        return Err(limit(LimitKind::Work));
    }
    let p = affine_map_point(inverse, edges[0].a).ok_or_else(|| invalid(0))?;
    let mut b = [p.x, p.y, p.x, p.y];
    for edge in edges {
        for point in [edge.a, edge.b] {
            let q = affine_map_point(inverse, point).ok_or_else(|| invalid(0))?;
            b[0] = b[0].min(q.x);
            b[1] = b[1].min(q.y);
            b[2] = b[2].max(q.x);
            b[3] = b[3].max(q.y);
        }
    }
    Ok(b)
}
fn map_shape_edges(
    view: SceneView<'_>,
    shape: &Shape,
    matrix: Affine,
    edges: &mut [Edge],
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    let range = shape.edges;
    let end = range.end().ok_or_else(arithmetic)?;
    if end > edges.len() {
        return Err(invalid(shape.source.element.start));
    }
    charge(control, range.count)?;
    *work = work.checked_add(range.count).ok_or_else(arithmetic)?;
    if *work > WORK_MAX {
        return Err(limit(LimitKind::Work));
    }
    for edge in &mut edges[range.first..end] {
        edge.a = affine_map_point(matrix, edge.a).ok_or_else(|| invalid(0))?;
        edge.b = affine_map_point(matrix, edge.b).ok_or_else(|| invalid(0))?;
    }
    let _ = view;
    Ok(())
}

/// Evaluate parsed overlays into a borrowed scene frame with owned changed tables.
pub fn evaluate_frame<'a>(
    view: SceneView<'a>,
    time_seconds: f64,
    control: &mut dyn WorkControl,
) -> Result<EvaluatedFrame<'a>> {
    evaluate_frame_with_budget(view, time_seconds, DEFAULT_FRAME_BYTE_BUDGET, control)
}

/// Evaluate a frame using the caller's configured budget for all published
/// frame-owned tables, including old-plus-new clip replacement overlap.
pub fn evaluate_frame_with_budget<'a>(
    view: SceneView<'a>,
    time_seconds: f64,
    byte_budget: usize,
    control: &mut dyn WorkControl,
) -> Result<EvaluatedFrame<'a>> {
    if byte_budget == usize::MAX {
        return Err(limit(LimitKind::ReservedBytes));
    }
    let overlay =
        evaluate_view_controlled(view.animation(), time_seconds, control).map_err(|e| match e {
            EvaluationError::InvalidTime => invalid(0),
            EvaluationError::InvalidTrack => diag(ErrorKind::Unsupported, 0),
            EvaluationError::OutOfMemory => oom(),
            EvaluationError::Canceled => diag(ErrorKind::Canceled, 0),
            EvaluationError::Limit => limit(LimitKind::Work),
            EvaluationError::Overflow => arithmetic(),
//! Owned clip updates for animated transform owners.
use vexel_geometry::{affine_compose, affine_identity, affine_map_point};
use vexel_scene::{
    Clip, ClipGeometry, Diagnostic, Edge, ErrorKind, EvaluatedFrame, LimitKind, Result, SceneView,
    Shape, ShapeId, TransformFrame, TransformId, WorkControl, WorkKind,
};

const CLIP_COPY_MAX_BYTES: usize = super::DEFAULT_FRAME_BYTE_BUDGET;
const CLIP_CHAIN_MAX: usize = 128;
const CLIP_OWNER_DEPTH_MAX: usize = 64;
const TRANSFORM_WORK_MAX: usize = 50_000_000;

fn invalid(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset,
    }
}
fn limit(kind: LimitKind) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(kind),
        offset: 0,
    }
}
fn arithmetic() -> Diagnostic {
    limit(LimitKind::Arithmetic)
}
fn oom() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::OutOfMemory,
        offset: 0,
    }
}
fn add(a: usize, b: usize) -> Result<usize> {
    a.checked_add(b).ok_or_else(arithmetic)
}
fn bytes<T>(count: usize) -> Result<usize> {
    count
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)
}

fn charge(
    control: &mut dyn WorkControl,
    kind: WorkKind,
    count: usize,
    work: &mut usize,
) -> Result<()> {
    let next = work.checked_add(count).ok_or_else(arithmetic)?;
    if next > TRANSFORM_WORK_MAX {
        *work = TRANSFORM_WORK_MAX;
        return Err(limit(LimitKind::Work));
    }
    let units = u64::try_from(count).map_err(|_| arithmetic())?;
    control.charge(kind, units).map_err(|stop| Diagnostic {
        kind: match stop {
            vexel_scene::Stop::Canceled => ErrorKind::Canceled,
            vexel_scene::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
            vexel_scene::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
        },
        offset: 0,
    })?;
    *work = next;
    Ok(())
}
fn clip_inverse(m: vexel_scene::Affine) -> Option<vexel_scene::Affine> {
    let det = m.a * m.d - m.b * m.c;
    if !det.is_finite() || det == 0.0 {
        return None;
    }
    let k = 1.0 / det;
    let out = vexel_scene::Affine {
        a: m.d * k,
        b: -m.b * k,
        c: -m.c * k,
        d: m.a * k,
        e: (m.c * m.f - m.d * m.e) * k,
        f: (m.b * m.e - m.a * m.f) * k,
    };
    vexel_geometry::affine_valid(out).then_some(out)
}

fn node_product(
    transforms: &[TransformFrame],
    target: TransformId,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<(vexel_scene::Affine, vexel_scene::Affine)> {
    let mut chain = [None; CLIP_CHAIN_MAX];
    let mut count = 0;
    let mut node = Some(target);
    while let Some(id) = node {
        if count == CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(0));
        }
        charge(control, WorkKind::ClipChain, 1, work)?;
        chain[count] = Some(id);
        count += 1;
        node = transforms[id.index()].parent;
    }
    let mut full = affine_identity();
    let mut before_suffix = affine_identity();
    while count != 0 {
        count -= 1;
        let id = chain[count].ok_or_else(|| invalid(0))?;
        let transform = transforms[id.index()];
        let local = affine_compose(transform.motion, transform.attribute)
            .ok_or_else(|| invalid(transform.source_offset))?;
        if id == target {
            before_suffix =
                affine_compose(full, local).ok_or_else(|| invalid(transform.source_offset))?;
        }
        let with_suffix = affine_compose(local, transform.suffix)
            .ok_or_else(|| invalid(transform.source_offset))?;
        full = affine_compose(full, with_suffix).ok_or_else(|| invalid(transform.source_offset))?;
    }
    Ok((full, before_suffix))
}

fn shape_has_node(
    shape: &Shape,
    transforms: &[TransformFrame],
    target: TransformId,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<bool> {
    let mut node = shape.source.transform_node;
    let mut depth = 0;
    while let Some(id) = node {
        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(shape.source.element.start));
        }
        charge(control, WorkKind::ClipChain, 1, work)?;
        if id == target {
            return Ok(true);
        }
        node = transforms[id.index()].parent;
        depth += 1;
    }
    Ok(false)
}

fn bounds_for_node(
    shapes: &[Shape],
    edges: &[Edge],
    transforms: &[TransformFrame],
    target: TransformId,
    inverse: vexel_scene::Affine,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<[f64; 4]> {
    let mut bounds: Option<[f64; 4]> = None;
    for shape in shapes {
        if !shape_has_node(shape, transforms, target, control, work)? {
            continue;
        }
        let segment = shape
            .edges
            .slice(edges)
            .ok_or_else(|| invalid(shape.source.element.start))?;
        for edge in segment {
            charge(control, WorkKind::ClipEdge, 1, work)?;
            for point in [edge.a, edge.b] {
                let local = affine_map_point(inverse, point)
                    .ok_or_else(|| invalid(shape.source.element.start))?;
                match &mut bounds {
                    Some(b) => {
                        b[0] = b[0].min(local.x);
                        b[1] = b[1].min(local.y);
                        b[2] = b[2].max(local.x);
                        b[3] = b[3].max(local.y);
                    }
                    None => bounds = Some([local.x, local.y, local.x, local.y]),
                }
            }
        }
    }
    bounds.ok_or_else(|| invalid(0))
}

fn update_clip_owner(
    shapes: &[Shape],
    clips: &mut [Clip],
    node: TransformId,
    full_inverse: vexel_scene::Affine,
    before_suffix_inverse: vexel_scene::Affine,
    bounds: Option<[f64; 4]>,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    for shape in shapes {
        charge(control, WorkKind::ClipChain, 1, work)?;
        let mut current = shape.clip;
        let mut depth = 0;
        while let Some(id) = current {
            if depth >= CLIP_OWNER_DEPTH_MAX || id.index() >= clips.len() {
                return Err(invalid(shape.source.element.start));
            }
            charge(control, WorkKind::ClipChain, 1, work)?;
            let clip = &mut clips[id.index()];
            if clip.owner_node == Some(node) {
                clip.user_inverse = if clip.owner_before_suffix {
                    before_suffix_inverse
                } else {
                    full_inverse
                };
                if let Some(b) = bounds {
                    if clip.object_bounding_box
                        && b.into_iter().all(f64::is_finite)
                        && b[2] >= b[0]
                        && b[3] >= b[1]
                    {
                        clip.bounds = b;
                    }
                }
            }
            current = clip.parent;
            depth += 1;
        }
    }
    Ok(())
}

fn update_clip_shape(
    shapes: &[Shape],
    edges: &[Edge],
    transforms: &[TransformFrame],
    clips: &mut [Clip],
    shape: &Shape,
    update_bounds: bool,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    let mut node = shape.source.transform_node;
    let mut depth = 0;
    while let Some(id) = node {
        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(shape.source.element.start));
        }
        let (full, before_suffix) = node_product(transforms, id, control, work)?;
        let full_inverse = clip_inverse(full).ok_or_else(|| invalid(shape.source.element.start))?;
        let attribute_inverse =
            clip_inverse(before_suffix).ok_or_else(|| invalid(shape.source.element.start))?;
        let bounds = if update_bounds {
            Some(bounds_for_node(
                shapes,
                edges,
                transforms,
                id,
                full_inverse,
                control,
                work,
            )?)
        } else {
            None
        };
        update_clip_owner(
            shapes,
            clips,
            id,
            full_inverse,
            attribute_inverse,
            bounds,
            control,
            work,
        )?;
        node = transforms[id.index()].parent;
        depth += 1;
    }
    Ok(())
}

fn clone_clip_table(
    view: SceneView<'_>,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<Vec<Clip>> {
    let mut estimate = bytes::<Clip>(view.clips.len())?;
    for clip in view.clips {
        charge(control, WorkKind::ClipChild, 1, work)?;
        estimate = add(estimate, bytes::<Edge>(clip.geometry.edges.len())?)?;
        estimate = add(
            estimate,
            bytes::<vexel_scene::ClipChild>(clip.geometry.shapes.len())?,
        )?;
    }
    if estimate > CLIP_COPY_MAX_BYTES {
        return Err(limit(LimitKind::Animation));
    }
    let mut output = Vec::new();
    output
        .try_reserve_exact(view.clips.len())
        .map_err(|_| oom())?;
    for source in view.clips {
        charge(control, WorkKind::ClipChild, 1, work)?;
        let mut edges = Vec::new();
        edges
            .try_reserve_exact(source.geometry.edges.len())
            .map_err(|_| oom())?;
        for edge in &source.geometry.edges {
            charge(control, WorkKind::ClipEdge, 1, work)?;
            edges.push(*edge);
        }
        let mut shapes = Vec::new();
        shapes
            .try_reserve_exact(source.geometry.shapes.len())
            .map_err(|_| oom())?;
        for child in &source.geometry.shapes {
            charge(control, WorkKind::ClipChild, 1, work)?;
            shapes.push(*child);
        }
        output.push(Clip {
            geometry: ClipGeometry { edges, shapes },
            parent: source.parent,
            owner_node: source.owner_node,
            owner_before_suffix: source.owner_before_suffix,
            object_bounding_box: source.object_bounding_box,
            bounds: source.bounds,
            user_inverse: source.user_inverse,
        });
    }
    let actual = actual_clip_capacity(&output, control, work)?;
    if actual > CLIP_COPY_MAX_BYTES {
        return Err(limit(LimitKind::Animation));
    }
    Ok(output)
}

fn actual_clip_capacity(
    clips: &Vec<Clip>,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<usize> {
    let mut total = clips
        .capacity()
        .checked_mul(std::mem::size_of::<Clip>())
        .ok_or_else(arithmetic)?;
    for clip in clips {
        charge(control, WorkKind::ClipChild, 1, work)?;
        let edges = clip
            .geometry
            .edges
            .capacity()
            .checked_mul(std::mem::size_of::<Edge>())
            .ok_or_else(arithmetic)?;
        let shapes = clip
            .geometry
            .shapes
            .capacity()
            .checked_mul(std::mem::size_of::<vexel_scene::ClipChild>())

            EvaluationError::Overflow => arithmetic(),
        })?;
    let mut builder = FrameBuilder::new(view, byte_budget)?;
    if !overlay.items.iter().any(|item| item.active) {
        return builder.finish(control);
    }
    let mut work = 0usize;
    let mut transforms = copy_table(view.transforms, control)?;
    let mut transform_seen = Vec::new();
    transform_seen
        .try_reserve_exact(view.transforms.len())
        .map_err(|_| oom())?;
    transform_seen.resize(view.transforms.len(), false);
    let mut world = Vec::new();
    world
        .try_reserve_exact(view.shapes.len())
        .map_err(|_| oom())?;
    for shape in view.shapes {
        world.push(product(view.transforms, shape, control, &mut work)?);
    }
    let mut edges = copy_table(view.edges, control)?;
    let mut colors = copy_table(view.edge_colors, control)?;
    let mut shapes = copy_table(view.shapes, control)?;
    let mut fills = copy_table(view.fill_paints, control)?;
    let mut strokes = copy_table(view.stroke_paints, control)?;
    let mut changed_edges = false;
    let mut changed_colors = false;
    let mut changed_shapes = false;
    let mut changed_fills = false;
    let mut changed_strokes = false;
    let has_clip_updates = !view.clips.is_empty()
        && overlay.items.iter().any(|item| {
            item.active
                && view
                    .animation()
                    .tracks
                    .get(item.track_index)
                    .is_some_and(|track| changes_clips(track, *item))
        });
    let mut clip_shape_flags = Vec::new();
    let mut clips = if !has_clip_updates {
        None
    } else {
        Some(clips::clone_clips_for_overlay(view, control)?)
    };
    if has_clip_updates {
        clip_shape_flags
            .try_reserve_exact(view.shapes.len())
            .map_err(|_| oom())?;
        clip_shape_flags.resize(view.shapes.len(), false);
    }
    for item in &overlay.items {
        if !item.active {
            continue;
        }
        charge(control, 1)?;
        work = work.checked_add(1).ok_or_else(arithmetic)?;
        if work > WORK_MAX {
            return Err(limit(LimitKind::Work));
        }
        let track = view
            .animation()
            .tracks
            .get(item.track_index)
            .ok_or_else(|| invalid(0))?;
        match track.kind {
            Kind::Transform | Kind::Motion => {
                let anim = if track.kind == Kind::Transform {
                    transform_value(track, item.value)
                        .ok_or_else(|| diag(ErrorKind::Unsupported, track.element.offset))?
                } else if item.value.kind == ValueKind::Motion {
                    let (s, c) = (item.value.number[2] * 0.017453292519943295769).sin_cos();
                    Affine {
                        a: c,
                        b: s,
                        c: -s,
                        d: c,
                        e: item.value.number[0],
                        f: item.value.number[1],
                    }
                } else {
                    return Err(diag(ErrorKind::Unsupported, track.element.offset));
                };
                let mut found = false;
                for (i, node) in transforms.iter_mut().enumerate() {
                    charge(control, 1)?;
                    count_work(&mut work, 1)?;
                    if node.source_offset != track.target.offset {
                        continue;
                    }
                    found = true;
                    if track.kind == Kind::Motion {
                        node.motion = affine_compose(node.motion, anim)
                            .ok_or_else(|| invalid(track.element.offset))?;
                    } else if track.additive_sum || transform_seen[i] {
                        node.attribute = affine_compose(node.attribute, anim)
                            .ok_or_else(|| invalid(track.element.offset))?;
                    } else {
                        node.attribute = anim;
                    }
                    transform_seen[i] = true;
                }
                if found {
                    for si in 0..shapes.len() {
                        let shape = shapes[si];
                        charge(control, 1)?;
                        count_work(&mut work, 1)?;
                        let mut n = shape.source.transform_node;
                        let mut has = false;
                        let mut depth = 0;
                        while let Some(id) = n {
                            if depth >= CHAIN_MAX || id.index() >= transforms.len() {
                                return Err(invalid(track.element.offset));
                            }
                            charge(control, 1)?;
                            count_work(&mut work, 1)?;
                            if transforms[id.index()].source_offset == track.target.offset {
                                has = true;
                                break;
                            }
                            n = transforms[id.index()].parent;
                            depth += 1;
                        }
                        if !has {
                            continue;
                        }
                        if has_effect(view, si, control, &mut work)? {
                            return Err(diag(ErrorKind::Unsupported, track.element.offset));
                        }
                        let next = product(&transforms, &shape, control, &mut work)?;
                        let delta = affine_compose(
                            next,
                            inverse(world[si], 1e-15)
                                .ok_or_else(|| invalid(track.element.offset))?,
                        )
                        .ok_or_else(|| invalid(track.element.offset))?;
                        map_shape_edges(view, &shape, delta, &mut edges, control, &mut work)?;
                        changed_edges = true;
                        world[si] = next;
                        let mut updated = shape;
                        updated.stroke_inverse = affine_compose(
                            updated.stroke_inverse,
                            inverse(delta, 1e-15).ok_or_else(|| invalid(track.element.offset))?,
                        )
                        .ok_or_else(|| invalid(track.element.offset))?;
                        if let Some(index) = updated.fill_paint {
                            if let Some(p) = fills.get_mut(index) {
                                if p.kind != PaintKind::Solid {
                                    p.user_inverse = affine_compose(
                                        p.user_inverse,
                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
                                    )
                                    .ok_or_else(|| invalid(0))?;
                                    changed_fills = true;
                                }
                            }
                        }
                        if let Some(index) = updated.stroke_paint {
                            if let Some(p) = strokes.get_mut(index) {
                                if p.kind != PaintKind::Solid {
                                    p.user_inverse = affine_compose(
                                        p.user_inverse,
                                        inverse(delta, 1e-15).ok_or_else(|| invalid(0))?,
                                    )
                                    .ok_or_else(|| invalid(0))?;
                                    changed_strokes = true;
                                }
                            }
                        }
                        shapes[si] = updated;
                        changed_shapes = true;
                        if !clip_shape_flags.is_empty() {
                            clip_shape_flags[si] = true;
                        }
                    }
                }
            }
            _ => apply_value(
                view,
                track,
                *item,
                &mut edges,
                &mut colors,
                &mut shapes,
                &mut fills,
                &mut strokes,
                &world,
                control,
                &mut work,
                &mut changed_edges,
                &mut changed_colors,
                &mut changed_shapes,
                &mut changed_fills,
                &mut changed_strokes,
                &mut clip_shape_flags,
            )?,
        }
        if let Some(clip_table) = clips.as_mut() {
            for si in 0..clip_shape_flags.len() {
                if clip_shape_flags[si] {
                    clips::update_clip_table_for_shape(
                        &transforms,
                        &shapes,
                        &edges,
                        clip_table,
                        si,
                        true,
                        control,
                        &mut work,
                    )?;
                    clip_shape_flags[si] = false;
                }
            }
        }
    }
    if changed_edges {
        builder.replace_edges(edges, control)?;
    }
    if changed_colors {
        builder.replace_colors(colors, control)?;
    }
    if changed_shapes {
        for (idx, value) in shapes.iter().enumerate() {
            let id = view.shape_id(idx).ok_or_else(|| invalid(0))?;
            if view.shapes.get(idx) != Some(value) {
                builder.set_shape(id, *value, control)?;
            }
        }
    }
    if changed_fills {
        for (i, p) in fills.into_iter().enumerate() {
            if view.fill_paints.get(i) != Some(&p) {
                builder.set_fill_paint(i, p, control)?;
            }
        }
    }
    if changed_strokes {
        for (i, p) in strokes.into_iter().enumerate() {
            if view.stroke_paints.get(i) != Some(&p) {
                builder.set_stroke_paint(i, p, control)?;
            }
        }
    }
    for (i, t) in transforms.into_iter().enumerate() {
        if view.transforms.get(i) != Some(&t) {
            let id = view.transform_id(i).ok_or_else(|| invalid(0))?;
            builder.set_transform(id, t, control)?;
        }
    }
    let mut frame = builder.finish(control)?;
    if let Some(clip_table) = clips {
        frame.replace_clips(clip_table, control)?;
    }
    Ok(frame)
}

fn has_effect(
    view: SceneView<'_>,
    shape: usize,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<bool> {
    for g in view.groups {
        charge(control, 1)?;
        *work = work.checked_add(1).ok_or_else(arithmetic)?;
        if *work > WORK_MAX {
            return Err(limit(LimitKind::Work));
        }
        if shape >= g.shapes.first
            && shape < g.shapes.end().ok_or_else(arithmetic)?
            && (g.filter.is_some() || g.mask.is_some())
        {
            return Ok(true);
        }
    }
    Ok(false)
use super::*;

pub(super) fn apply_value(
    view: SceneView<'_>,
    t: &Track,
    item: OverlayItem,
    edges: &mut [Edge],
    colors: &mut [[u8; 4]],
    shapes: &mut [Shape],
    fills: &mut [Paint],
    _strokes: &mut [Paint],
    world: &[Affine],
    control: &mut dyn WorkControl,
    work: &mut usize,
    ce: &mut bool,
    cc: &mut bool,
    cs: &mut bool,
    cf: &mut bool,
    _csp: &mut bool,
    clip_shape_flags: &mut [bool],
) -> Result<()> {
    let mut descendant = false;
    let mut direct = false;
    let target_end = t
        .target
        .offset
        .checked_add(t.target.length)
        .ok_or_else(arithmetic)?;
    for (i, shape) in shapes.iter_mut().enumerate() {
        charge(control, 1)?;
        *work = work.checked_add(1).ok_or_else(arithmetic)?;
        if *work > WORK_MAX {
            return Err(limit(LimitKind::Work));
        }
        let mut node = shape.source.transform_node;
        let mut depth = 0;
        let mut in_target = shape.source.element.start >= t.target.offset
            && shape.source.element.start < target_end;
        while let Some(id) = node {
            if depth >= CHAIN_MAX {
                return Err(limit(LimitKind::Animation));
            }
            let n = view
                .transform(id)
                .ok_or_else(|| invalid(t.element.offset))?;
            charge(control, 1)?;
            count_work(work, 1)?;
            if n.source_offset >= t.target.offset && n.source_offset < target_end {
                in_target = true;
            }
            node = n.parent;
            depth += 1;
        }
        if !in_target {
            continue;
        }
        descendant = true;
        let is_direct = shape.source.element.start == t.target.offset
            || shape.source.transform_node.is_some_and(|id| {
                view.transform(id)
                    .is_some_and(|n| n.source_offset == t.target.offset)
            });
        if !is_direct {
            continue;
        }
        direct = true;
        match t.attribute {
            Attribute::Fill if item.value.kind == ValueKind::Color => {
                let r = shape.edges;
                if r.end().is_none_or(|e| e > colors.len()) {
                    return Err(invalid(t.element.offset));
                }
                charge(control, r.count)?;
                for c in &mut colors[r.first..r.first + r.count] {
                    *c = item.value.rgba;
                }
                *cc = true;
            }
            Attribute::Stroke if item.value.kind == ValueKind::Color => {
                shape.stroke.rgba = item.value.rgba;
                *cs = true;
            }
            Attribute::Opacity | Attribute::FillOpacity if item.value.kind == ValueKind::Number => {
                let op = item.value.number[0].clamp(0., 1.);
                let r = shape.edges;
                if r.end().is_none_or(|e| e > colors.len()) {
                    return Err(invalid(t.element.offset));
                }
                charge(control, r.count)?;
                for c in &mut colors[r.first..r.first + r.count] {
                    c[3] = (f64::from(c[3]) * op + 0.5).floor() as u8;
                }
                *cc = true;
                if t.attribute == Attribute::Opacity {
                    shape.stroke.rgba[3] =
                        (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
                    *cs = true;
                }
            }
            Attribute::StrokeOpacity if item.value.kind == ValueKind::Number => {
                let op = item.value.number[0].clamp(0., 1.);
                shape.stroke.rgba[3] = (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
                *cs = true;
            }
            Attribute::StrokeWidth | Attribute::StrokeDashoffset
                if item.value.kind == ValueKind::Number =>
            {
                let v = item.value.number[0];
                if v.abs() > 1e6 || (t.attribute == Attribute::StrokeWidth && v < 0.) {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                if t.attribute == Attribute::StrokeWidth {
                    shape.stroke.width = v
                } else {
                    shape.stroke.dash_offset = v
                }
                *cs = true;
            }
            Attribute::D => return Err(diag(ErrorKind::Unsupported, t.element.offset)),
            Attribute::X
            | Attribute::Y
            | Attribute::Cx
            | Attribute::Cy
            | Attribute::Width
            | Attribute::Height
            | Attribute::Rx
            | Attribute::Ry
            | Attribute::R
                if item.value.kind == ValueKind::Number =>
            {
                if has_effect(view, i, control, work)? {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let delta = item.value.number[0] - t.base_value.number[0];
                if !delta.is_finite() || delta.abs() > 1e6 {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let mut local = affine_identity();
                match t.attribute {
                    Attribute::X | Attribute::Cx => local.e = delta,
                    Attribute::Y | Attribute::Cy => local.f = delta,
                    _ => {
                        let base = t.base_value.number[0];
                        if base <= 0. {
                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
                        }
                        let scale = item.value.number[0] / base;
                        if !scale.is_finite() || scale < 0. || scale > 1e6 {
                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
                        }
                        let inv = inverse(world[i], 1e-15)
                            .ok_or_else(|| diag(ErrorKind::Unsupported, t.element.offset))?;
                        let b = shape_bounds(shape, edges, inv, control, work)?;
                        if t.attribute == Attribute::Height || t.attribute == Attribute::Ry {
                            local.d = scale;
                            local.f = b[1] * (1. - scale);
                        } else {
                            let center = if t.attribute == Attribute::R {
                                (b[0] + b[2]) * 0.5
                            } else {
                                b[0]
                            };
                            local.a = scale;
                            local.e = center * (1. - scale);
                            if t.attribute == Attribute::R {
                                local.d = scale;
                                local.f = ((b[1] + b[3]) * 0.5) * (1. - scale);
                            }
                        }
                    }
                }
                if shape
                    .fill_paint
                    .is_some_and(|p| fills.get(p).is_some_and(|p| p.kind == PaintKind::Pattern))
                {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let matrix = affine_compose(
                    affine_compose(world[i], local).ok_or_else(|| invalid(0))?,
                    inverse(world[i], 1e-15).ok_or_else(|| invalid(0))?,
                )
                .ok_or_else(|| invalid(0))?;
                map_shape_edges(view, shape, matrix, edges, control, work)?;
                *ce = true;
                if !clip_shape_flags.is_empty() {
                    clip_shape_flags[i] = true;
                }
                if let Some(p) = shape.fill_paint.and_then(|n| fills.get_mut(n)) {
                    if p.object_bounding_box
                        && (p.kind == PaintKind::Linear || p.kind == PaintKind::Radial)
                    {
                        p.bounds = shape_bounds(
                            shape,
                            edges,
                            inverse(world[i], 1e-15).ok_or_else(|| invalid(0))?,
                            control,
                            work,
                        )?;
                        *cf = true;
                    }
                }
            }
            _ => return Err(diag(ErrorKind::Unsupported, t.element.offset)),
        }
    }
    if descendant && !direct {
        return Err(diag(ErrorKind::Unsupported, t.element.offset));
    }
    Ok(())
}
static bool checked_bytes(size_t count, size_t stride, size_t *out)
{
    if (count != 0U && stride > SIZE_MAX / count) return false;
    *out = count * stride;
    return true;
}

static bool consume_work(size_t *work, size_t amount)
{
    if (work == NULL || *work >= ANIMATION_TRANSFORM_WORK_MAX ||
        amount > ANIMATION_TRANSFORM_WORK_MAX - *work) {
        if (work != NULL) *work = ANIMATION_TRANSFORM_WORK_MAX;
        return false;
    }
    *work += amount;
    return true;
}

static bool shape_in_target(const svg_shape_document *document,
                            size_t shape, const svg_anim_track *track,
                            size_t *work)
{
    return true;
