    edges.try_reserve_exact(capacity_bytes / std::mem::size_of::<Edge>()).unwrap();
    edges.extend_from_slice(&source.geometry.edges);
    Clip { geometry: ClipGeometry { edges, shapes: source.geometry.shapes.clone() }, parent: source.parent,
