    let fixture = fixture(\"<animate attributeName='width' from='8' to='4' dur='2s' fill='freeze'/>\", \"M1 1 L9 1 L9 9 L1 9 Z\", true);
    let policy = 128 * 1024 * 1024;
    let mut frame = vexel_svg_animation_frame::evaluate_frame(fixture.graph.root(), 1.0, policy, &mut Control::new(u64::MAX)).unwrap();
    for _ in 0..2 {
        let replacement = vec"'![capacity_clip(&frame.view().clips[0], 33 * 1024 * 1024)];
        frame.replace_clips(replacement, &mut Control::new(u64::MAX)).unwrap();
    }
    assert!(frame.memory_stats().peak_live_bytes > 64 * 1024 * 1024);
    assert!(frame.memory_stats().peak_live_bytes <= policy);
    let before = frame.memory_stats();
    let bounds = frame.view().clips[0].bounds;
    let excessive_clip = vec![capacity_clip(&frame.view().clips[0], 65 * 1024 * 1024)];
    assert_eq!(frame.replace_clips(excessive_clip, &mut Control::new(u64::MAX)).unwrap_err().kind, ErrorKind::Limit(LimitKind::Animation));
